// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait FlightReadinessOwner_governorProcess_flightReadinessOwner_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.DroneLifecycleEnergyGovernorSystem_Instance_governorProcess_flightReadinessOwner)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.DroneLifecycleEnergyGovernorSystem_Instance_governorProcess_flightReadinessOwner)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.DroneLifecycleEnergyGovernorSystem_Instance_governorProcess_flightReadinessOwner)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.DroneLifecycleEnergyGovernorSystem_Instance_governorProcess_flightReadinessOwner)
  }

  /** helper function to set the values of all input ports.
   * @param navigationIn payload for data port navigationIn
   * @param flightControlIn payload for data port flightControlIn
   * @param batteryIn payload for data port batteryIn
   */
  def put_concrete_inputs(navigationIn : Drone_Lifecycle_Energy_Governor.NavigationReport.Type,
                          flightControlIn : Drone_Lifecycle_Energy_Governor.FlightControlReport.Type,
                          batteryIn : Drone_Lifecycle_Energy_Governor.BatteryStateFacts): Unit = {
    put_navigationIn(navigationIn)
    put_flightControlIn(flightControlIn)
    put_batteryIn(batteryIn)
  }


  /** helper function to check FlightReadinessOwner_governorProcess_flightReadinessOwner's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param readinessOut method that will be called with the value of the outgoing data
   *        port 'readinessOut'.
   */
  def check_concrete_output(readinessOut: Base_Types.Boolean => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val readinessOutValue: Base_Types.Boolean = get_readinessOut().get
    if(!readinessOut(readinessOutValue)) {
      testFailures = testFailures :+ st"'readinessOut' did not match expected: value of the outgoing data port is ${readinessOutValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_navigationIn(value : Drone_Lifecycle_Energy_Governor.NavigationReport.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.DroneLifecycleEnergyGovernorSystem_Instance_governorProcess_flightReadinessOwner.operational_api.navigationIn_Id, Drone_Lifecycle_Energy_Governor.NavigationReport_Payload(value))
  }

  // setter for in DataPort
  def put_flightControlIn(value : Drone_Lifecycle_Energy_Governor.FlightControlReport.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.DroneLifecycleEnergyGovernorSystem_Instance_governorProcess_flightReadinessOwner.operational_api.flightControlIn_Id, Drone_Lifecycle_Energy_Governor.FlightControlReport_Payload(value))
  }

  // setter for in DataPort
  def put_batteryIn(value : Drone_Lifecycle_Energy_Governor.BatteryStateFacts): Unit = {
    Art.insertInInfrastructurePort(Arch.DroneLifecycleEnergyGovernorSystem_Instance_governorProcess_flightReadinessOwner.operational_api.batteryIn_Id, Drone_Lifecycle_Energy_Governor.BatteryStateFacts_Payload(value))
  }

  // getter for out DataPort
  def get_readinessOut(): Option[Base_Types.Boolean] = {
    val value: Option[Base_Types.Boolean] = get_readinessOut_payload() match {
      case Some(Base_Types.Boolean_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port readinessOut.  Expecting 'Base_Types.Boolean_Payload' but received ${v}")
      case _ => None[Base_Types.Boolean]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_readinessOut_payload(): Option[Base_Types.Boolean_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.DroneLifecycleEnergyGovernorSystem_Instance_governorProcess_flightReadinessOwner.initialization_api.readinessOut_Id).asInstanceOf[Option[Base_Types.Boolean_Payload]]
  }

}
